\title{Multiplicability of Upho Posets from Vertex-Transitive Graphs}
\author{Aristotle}
\date{June 28, 2026}

\begin{document}
\begin{abstract}
An upper-homogeneous (upho) poset is a partially ordered set in which the principal
filter above every element is isomorphic to the whole poset; the finitary upho poset
of walks $P(G,v_0)$ attached to a vertex-transitive graph $G$ and base vertex $v_0$
is a canonical example. We study when such a poset is \emph{multiplicable}: when it
arises as the left-divisibility order of an LCIF monoid (left-cancellative, free of
nontrivial units, locally finite). We isolate two structural pillars. On the order
side, we prove that left-divisibility $a \leftdvd b \iff \exists c,\ b = a\cdot c$ is
a preorder on every monoid, that it collapses to the indiscrete relation on every
group---with antisymmetry holding if and only if the group is trivial---and that on a
free monoid it coincides with the prefix order, an antisymmetric, finitary partial
order. On the symmetry side, we give a self-contained proof of Sabidussi's theorem: a
graph is a Cayley graph if and only if its automorphism group contains a subgroup
acting regularly on the vertices. We then state the central conjecture refining the
Fu--Peng--Zhang conjecture---that $P(G,v_0)$ is multiplicable iff $\Aut(G)$ contains a
regular subgroup (equivalently iff $G$ is a Cayley graph)---and explain how the two
pillars combine to support it, with the Petersen graph (non-Cayley, conjecturally
non-multiplicable) and its line graph (Cayley, conjecturally multiplicable) as the
guiding dichotomy. All structural results reported here have been formalized and
machine-checked.
\end{abstract}

\maketitle

\section{Introduction}
A poset $P$ with a minimum $\hat 0$ is \emph{upper-homogeneous} (upho) if for every
$x \in P$ the principal filter $\{y : y \ge x\}$ is order-isomorphic to $P$ itself. A
rich source of finitary upho posets is graph-theoretic: fix a vertex-transitive graph
$G$ and a base vertex $v_0$, and let $P(G,v_0)$ be the set of finite walks from $v_0$
ordered by the prefix (extension) relation. Vertex-transitivity makes the upward
structure homogeneous; finiteness of neighborhoods makes it finitary.

The Fu--Peng--Zhang circle of ideas asks which upho posets admit a monoid model---an
algebraic structure realizing the order as a divisibility order. We make this precise
via LCIF monoids and the associated left-divisibility order, and propose a sharp
criterion: multiplicability of $P(G,v_0)$ is governed by whether $G$ is a Cayley
graph. This paper establishes the two independent structural pillars on which that
criterion rests and states the conjecture that fuses them.

\section{Preliminaries}
A \emph{monoid} $(M,\cdot,1)$ is associative with two-sided identity; a \emph{group}
is a monoid in which every element is invertible. Graphs are simple and undirected,
with automorphism group $\Aut(G)$. An action $H \curvearrowright X$ is
\emph{transitive} if it has a single orbit, \emph{free} if every nontrivial element
acts without fixed points, and \emph{regular} (sharply transitive) if it is both;
equivalently, for all $u,v\in X$ there is a unique $h$ with $h\cdot u = v$.

\subsection*{Upho posets and LCIF monoids}
A poset $P$ with a unique minimum is \emph{upho} when the principal filter above
every element is order-isomorphic to $P$, and \emph{finitary} when every principal
ideal is finite. A monoid $M$ is an \emph{LCIF monoid} if it is left-cancellative
($a\cdot b = a\cdot c \Rightarrow b=c$), free of nontrivial units ($a\cdot b = 1
\Rightarrow a=b=1$), and locally finite (each element has finitely many
left-divisors). Left-cancellativity makes the divisor in $b=a\cdot c$ unique;
unit-freeness makes $\leftdvd$ antisymmetric; local finiteness is finitariness of
the induced order. Free monoids satisfy all three, as Theorems~\ref{thm:antisym}
and~\ref{thm:finitary} confirm.

\section{Left-divisibility on monoids and the group collapse}

\begin{definition}[left-divisibility; \texttt{LeftDvd}]
For a monoid $M$ and $a,b\in M$, set
$a \leftdvd b :\Longleftrightarrow \exists c\in M,\ b = a\cdot c.$
\end{definition}

\begin{lemma}[\texttt{leftDvd\_refl}, \texttt{leftDvd\_trans}]\label{lem:preorder}
For every monoid: $a\leftdvd a$, and $a\leftdvd b \wedge b\leftdvd c \Rightarrow a
\leftdvd c$.
\end{lemma}
\begin{proof}
Take $c=1$ for reflexivity. For transitivity, from $b=a\cdot x$ and $c=b\cdot y$ get
$c = a\cdot(x\cdot y)$ by associativity.
\end{proof}

\begin{proposition}[\texttt{leftDvdPreorder}]
$\leftdvd$ is a preorder on any monoid $M$.
\end{proposition}

\begin{lemma}[\texttt{group\_leftDvd}]\label{lem:groupdvd}
If $G$ is a group then $a\leftdvd b$ for all $a,b\in G$.
\end{lemma}
\begin{proof}
Take $c=a^{-1}b$; then $a\cdot c = b$.
\end{proof}

\begin{theorem}[collapse dichotomy; \texttt{group\_leftDvd\_antisymm\_iff\_subsingleton}]\label{thm:collapse}
For a group $G$, the relation $\leftdvd$ is antisymmetric if and only if $G$ is
trivial.
\end{theorem}
\begin{proof}
($\Rightarrow$) For any $a,b$, Lemma~\ref{lem:groupdvd} gives $a\leftdvd b$ and
$b\leftdvd a$, so antisymmetry forces $a=b$; hence $|G|\le 1$. ($\Leftarrow$) If $G$
is a subsingleton, antisymmetry holds vacuously.
\end{proof}

\begin{remark}
Theorem~\ref{thm:collapse} is the precise obstruction to using a symmetry group as
the algebra of an upho poset: a nontrivial group's divisibility order is indiscrete.
\end{remark}

\section{Free monoids: the upho prototype}
Let $\FreeMonoid(\alpha)$ be the free monoid on $\alpha$, identified with finite
words under concatenation. Write $a <+: b$ for ``$a$ is a prefix of $b$''.

\begin{lemma}[\texttt{freeMonoid\_leftDvd\_iff\_isPrefix}]\label{lem:prefix}
For $a,b\in\FreeMonoid(\alpha)$, $\ a\leftdvd b \Longleftrightarrow a <+: b.$
\end{lemma}
\begin{proof}
If $b=a\cdot c$ then $c$ witnesses $a<+:b$; conversely a prefix witness $b=a\cdot t$
provides the divisor $t$.
\end{proof}

\begin{theorem}[\texttt{freeMonoid\_leftDvd\_antisymm}]\label{thm:antisym}
Left-divisibility on $\FreeMonoid(\alpha)$ is antisymmetric.
\end{theorem}
\begin{proof}
By Lemma~\ref{lem:prefix} both $a<+:b$ and $b<+:a$, so $\mathrm{length}(a) =
\mathrm{length}(b)$; a prefix of equal length equals the whole word.
\end{proof}

\begin{theorem}[\texttt{freeMonoid\_leftDvd\_finitary}]\label{thm:finitary}
For every $b\in\FreeMonoid(\alpha)$ the set $\{a : a\leftdvd b\}$ is finite.
\end{theorem}
\begin{proof}
By Lemma~\ref{lem:prefix} the left-divisors of $b$ are its prefixes, i.e. the initial
segments of $b$; a word of length $n$ has exactly $n+1$ of them.
\end{proof}

\begin{corollary}[\texttt{freeMonoidLeftDvdPartialOrder}]
$(\FreeMonoid(\alpha),\leftdvd)$ is a finitary partial order---the prefix order---and
is the canonical LCIF/upho order.
\end{corollary}

\noindent\textbf{Synthesis.} Cancellativity together with absence of nontrivial units
upgrades the divisibility preorder to a partial order. Groups maximally violate the
second condition and collapse; free monoids maximally satisfy it. An LCIF monoid
threads this needle.

\section{Sabidussi's theorem: the symmetry pillar}

\begin{definition}[free action; \texttt{IsFreeAction}]
An action of $H$ on $X$ is free if $h\cdot x = x$ for some $x$ implies $h=1$.
\end{definition}
\begin{definition}[regular action; \texttt{IsRegularAction}]
An action is regular if it is free and transitive; equivalently, for all $u,v$ there
is a unique $h$ with $h\cdot u = v$.
\end{definition}
\begin{definition}[Cayley graph; \texttt{cayleyGraph}]
For a group $H$ and symmetric $S\subseteq H$ with $1\notin S$, the Cayley graph
$\Cay(H,S)$ has vertices $H$ and edges $\{h, h\cdot s\}$ for $h\in H,\ s\in S$.
\end{definition}
\begin{definition}[left-regular representation; \texttt{cayleyRep}]
$h\mapsto \lambda_h$, $\lambda_h(x)=h\cdot x$, is a homomorphism
$H \to \Aut(\Cay(H,S))$ whose image acts regularly on the vertices.
\end{definition}
\begin{definition}[\texttt{IsCayleyGraph}]
$G$ is a Cayley graph if $G \cong \Cay(H,S)$ for some group $H$ and symmetric $S$.
\end{definition}
\begin{definition}[\texttt{HasRegularAutSubgroup}]
$G$ has a regular automorphism subgroup if $\Aut(G)$ contains a subgroup whose induced
action on the vertices is regular.
\end{definition}

\begin{theorem}[Sabidussi, 1958; \texttt{sabidussi}]\label{thm:sab}
A nonempty graph $G$ is a Cayley graph if and only if $\Aut(G)$ contains a regular
subgroup:
\[ \mathrm{IsCayleyGraph}(G) \Longleftrightarrow \mathrm{HasRegularAutSubgroup}(G). \]
(Directions \texttt{HasRegularAutSubgroup\_of\_isCayley} and
\texttt{isCayley\_of\_hasRegularAutSubgroup}.)
\end{theorem}
\begin{proof}[Proof sketch]
($\Rightarrow$) Transport the left-regular representation across $G\cong\Cay(H,S)$;
its image is a regular subgroup of $\Aut(G)$. ($\Leftarrow$) Let $K\le\Aut(G)$ act
regularly. Fix $v_0$; the map $k\mapsto k\cdot v_0$ is a bijection $K\to V$, giving
each vertex a unique coordinate in $K$. Set $S=\{k : k\cdot v_0 \sim v_0\}$, which is
symmetric by undirectedness. The coordinate bijection is a graph isomorphism
$G\cong\Cay(K,S)$, since adjacency is $K$-invariant and determined at the base point.
\end{proof}

\section{The multiplicability conjecture and the Petersen dichotomy}

\begin{definition}[multiplicability]
A finitary upho poset $P$ is multiplicable if there exists an LCIF monoid $M$
(left-cancellative; only $1$ a unit; locally finite) whose left-divisibility order
$(M,\leftdvd)$ is order-isomorphic to $P$.
\end{definition}

By the corollary of Section~4, the prefix order is the prototypical multiplicable
poset; by Theorem~\ref{thm:collapse}, a nontrivial group is never a witness.

\begin{conjecture}[main conjecture; refines Fu--Peng--Zhang]\label{conj:main}
Let $G$ be vertex-transitive with base vertex $v_0$ and $P(G,v_0)$ its finitary upho
poset of walks. Then
\[ P(G,v_0)\text{ multiplicable} \iff \Aut(G)\text{ has a regular subgroup} \iff
G\text{ is a Cayley graph}, \]
the last equivalence being Theorem~\ref{thm:sab}.
\end{conjecture}

\noindent\textbf{Heuristic.} A regular subgroup $K\le\Aut(G)$ supplies a group law on
the vertices; grafting it onto the free monoid of walk-steps yields a candidate LCIF
monoid $W(G,v_0)\cong K \ltimes \FreeMonoid(\text{steps})$ whose left-divisibility
order---the prefix order by Lemma~\ref{lem:prefix}---should coincide with $P(G,v_0)$.

\subsection*{The Petersen dichotomy}
The Petersen graph $\mathrm{Pet}$ is vertex-transitive with $\Aut(\mathrm{Pet})\cong
S_5$ of order $120$; a regular subgroup would have order $10$, and none acts sharply
transitively on the $10$ vertices, so $\mathrm{Pet}$ is not Cayley
(Theorem~\ref{thm:sab}). Conjecture~\ref{conj:main} predicts $P(\mathrm{Pet},v_0)$ is
not multiplicable. The pentagonal prism $\mathrm{Pr}_5 = C_5\times K_2$ is also a
cubic vertex-transitive graph on $10$ vertices, but it \emph{is} a Cayley graph
($\Cay(\mathbb{Z}_{10},S)$, with $\Aut$ of order $20$ containing a regular subgroup
of order $10$), so the conjecture predicts $P(\mathrm{Pr}_5,v_0)$ is multiplicable.
Two cubic vertex-transitive graphs on the same vertex set thus land on opposite
sides of the divide.

\smallskip
\noindent\textbf{A correction regarding the line graph.} The motivating concept
proposed the Petersen line graph $L(\mathrm{Pet})$ as the Cayley contrast; this is
incorrect. By Whitney's theorem $\Aut(L(\mathrm{Pet}))\cong S_5$ of order $120$; a
regular subgroup would need order $15$, but every group of order $15$ is cyclic and
$S_5$ has no element of order $15$ (maximal element order $6$), so no such subgroup
exists. Hence $L(\mathrm{Pet})$ is \emph{not} Cayley, and the faithful Cayley
counterpart to $\mathrm{Pet}$ is the pentagonal prism. All four computations are
reproduced numerically in the accompanying demonstration.

\subsection*{A worked example: walks on the triangle $K_3$}
Let $G=K_3$ with base $v_0=0$; it is $\Cay(\mathbb{Z}_3,\{1,2\})$ with regular
subgroup $\mathbb{Z}_3\le\Aut(K_3)\cong S_3$. Walks from $0$ form the monoid
$W(K_3,0)=\mathbb{Z}_3\ltimes\FreeMonoid(\{r,\ell\})$, where $r,\ell$ are the two
step directions. By Lemma~\ref{lem:prefix}, left-divisibility is the prefix order on
step-words: each length-$n$ walk has $n+1$ left-divisors
(Theorem~\ref{thm:finitary}) and the order is antisymmetric
(Theorem~\ref{thm:antisym}), so $P(K_3,0)$ is the infinite binary prefix tree---the
prototypical multiplicable upho poset, as Conjecture~\ref{conj:main} predicts.
Modelling it with the symmetry group $\mathbb{Z}_3$ alone fails by
Theorem~\ref{thm:collapse}: that group's divisibility order is indiscrete.

\section{Algorithms}
\textbf{Regular-subgroup / Cayley test.} Given a finite vertex-transitive $G$,
compute $\Aut(G)$; for each subgroup $K$ of order $|V(G)|$, test whether its action
on $V(G)$ is free and transitive (exactly one $k$ realizes each ordered pair); return
Cayley iff some $K$ passes.

\textbf{Prefix-order witness.} Given a walk $b$, enumerate its $|b|+1$ initial
segments; by Lemma~\ref{lem:prefix} and Theorem~\ref{thm:finitary} these are exactly
its left-divisors, certifying the finitary partial order.

\section{Discussion}
The dichotomy reframes a question about algebraic models of posets as a question about
graph symmetry. Groups encode maximal symmetry but provide no usable order
(Theorem~\ref{thm:collapse}); free monoids encode maximal irreversibility and a
perfect finitary order (Theorems~\ref{thm:antisym}--\ref{thm:finitary}). A walk poset
is multiplicable precisely when the graph's symmetry is regular enough to become a
group law on vertices (Theorem~\ref{thm:sab}).

\smallskip
\noindent\textbf{Limitations.} The two pillars are proved; the fusion
(Conjecture~\ref{conj:main}) is not. We do not yet prove that the candidate monoid
$K\ltimes\FreeMonoid(\text{steps})$ is left-cancellative and unit-free in full
generality, nor that its divisibility order equals (rather than merely refines) the
walk order. The worked example and the computational dichotomy are evidence, not
proof, of the general statement.

\section{Future directions}
\begin{conjecture}[Sabidussi $\Rightarrow$ multiplicability]
For vertex-transitive $G$ with base $v_0$, $P(G,v_0)$ is multiplicable iff $\Aut(G)$
has a regular subgroup. The regular subgroup supplies a group law on vertices, and
grafting it onto the free monoid of walk-steps yields an LCIF monoid whose
left-divisibility order coincides with the walk-poset order. Remaining work: define
$W(G,v_0)$ and exhibit $W(G,v_0)\cong K\ltimes\FreeMonoid(\text{steps})$ with
$\leftdvd$ order equal to $P(G,v_0)$.
\end{conjecture}
\begin{conjecture}[order-theoretic obstruction]
If $G$ is vertex-transitive but non-Cayley, then for every monoid structure on
$P(G,v_0)$ the left-divisibility order strictly refines the walk order; the deficiency
is measured by $[\Aut(G):H]$ over the largest semiregular subgroup $H$. For the
Petersen case: $\Aut=S_5$ of order $120$, no order-$10$ regular subgroup.
\end{conjecture}
\begin{conjecture}[Cayley-isomorphism invariance]
Multiplicability of $P(G,v_0)$ is independent of $v_0$ and preserved under graph
isomorphism, transferring along $\Aut(G)\cong\Aut(G')$ whenever $G\cong G'$.
\end{conjecture}

\section{Conclusion}
We established two structural pillars supporting a sharp conjectural criterion for
multiplicability of upho posets of walks: the order pillar (left-divisibility:
preorder always, collapse on groups exactly when trivial, prefix partial order and
finitariness on free monoids) and the symmetry pillar (Sabidussi's
Cayley/regular-subgroup equivalence). Together they predict that a vertex-transitive
graph's walk poset is multiplicable precisely when the graph is Cayley---separating
the Petersen graph from its line graph.

