"""Group collapse dichotomy for left-divisibility on cyclic groups Z/n.

Exercises Lemma 3.4 (in a group everybody left-divides everybody) and Theorem 3.5
(antisymmetry of left-divisibility on a group holds iff the group is trivial).
"""
from __future__ import annotations

def zmod_left_divides(n: int, a: int, b: int) -> bool:
    return any((a + c) % n == b % n for c in range(n))

def universal(n: int) -> bool:
    return all(zmod_left_divides(n, a, b) for a in range(n) for b in range(n))

def antisymmetric(n: int) -> bool:
    return all((not (zmod_left_divides(n, a, b) and zmod_left_divides(n, b, a))) or a == b
               for a in range(n) for b in range(n))

if __name__ == "__main__":
    for n in (1, 2, 3, 5, 7):
        print(f"Z/{n}: every element divides every other = {universal(n)}; "
              f"antisymmetric (=> trivial group) = {antisymmetric(n)}")

