function AUTOMORPHISMS(G):
  n <- |V(G)|; image <- [-1]*n; used <- [false]*n; result <- []
  function CONSISTENT(v, w):
    if deg(v) != deg(w): return false
    for u in 0..v-1:
      if (u~v) != (image[u]~w): return false
    return true
  function BACKTRACK(v):
    if v = n: append copy(image) to result; return
    for each w not used with CONSISTENT(v, w):
      image[v] <- w; used[w] <- true
      BACKTRACK(v+1)
      used[w] <- false; image[v] <- -1
  BACKTRACK(0); return result

