function HAS_REGULAR_AUT_SUBGROUP(Aut, n):
  FPF <- { p in Aut : p has no fixed point }
  for a in FPF:
    H <- CLOSURE({a}, cap = n+1)
    if H != NONE and REGULAR(H, n): return H
  for (a, b) in FPF x FPF:
    H <- CLOSURE({a, b}, cap = n+1)
    if H != NONE and REGULAR(H, n): return H
  return NONE
function REGULAR(H, n):
  return |H| = n and (all non-identity h in H are fixed-point-free)
         and { h(0) : h in H } = {0,...,n-1}

